# ---------------------------------------------------------------- assets ---
def _tk_png(data_b64):
    """Embedded base64 PNG -> PhotoImage (koi PIL/file ki zaroorat nahi)."""
    if not data_b64:
        return None
    try:
        return tk.PhotoImage(data=data_b64)
    except Exception:
        return None


# ------------------------------------------------------------ root mode ---
# GUI environment variables that must survive the switch to root.
_PASSTHROUGH = (
    "DISPLAY", "WAYLAND_DISPLAY", "XAUTHORITY", "XDG_RUNTIME_DIR",
    "XDG_SESSION_TYPE", "XDG_CURRENT_DESKTOP", "XDG_SESSION_DESKTOP",
    "DBUS_SESSION_BUS_ADDRESS", "GDK_BACKEND", "LANG", "LANGUAGE",
    "LC_ALL", "LC_CTYPE", "NO_AT_BRIDGE", "TERM", "COLORTERM",
)


def is_root():
    return os.geteuid() == 0


def ensure_root():
    """Re-exec this script as root the moment it starts (pkexec -> sudo)."""
    if os.name != "posix" or is_root():
        return
    if os.environ.get("KALI_UNI_ELEV") == "1":        # elevation loop guard
        return
    exe = sys.executable or "/usr/bin/python3"
    script = os.path.abspath(__file__)
    env = {k: os.environ[k] for k in _PASSTHROUGH if os.environ.get(k)}
    env["KALI_UNI_ELEV"] = "1"
    pairs = [f"{k}={v}" for k, v in env.items() if v]

    for argv in (
        ["pkexec", "env", *pairs, exe, script],
        ["sudo", "-E", "--", exe, script],
    ):
        try:
            os.execvpe(argv[0], argv, env)
        except (FileNotFoundError, OSError):
            continue
    # If we reach here no elevator worked — continue without root; the GUI
    # will show a NO ROOT badge and apt errors will appear in the log.
    print("[Kali Uninstaller] WARNING: root elevation failed, "
          "chaltay waqt permission errors aa sakte hain.", file=sys.stderr)


# --------------------------------------------------------------- doctor ---
def _run_doctor():
    """--doctor: har cheez check karke exact fix command print karo."""
    print("== KALI UNINSTALLER -- DOCTOR ==")
    ok = True
    print(f"[OK] Python {sys.version.split()[0]}")
    try:
        import tkinter                                   # noqa: F401
        print("[OK] tkinter (GUI library)")
    except Exception as exc:
        print(f"[X] tkinter missing ({exc})")
        print("    FIX: sudo apt update && sudo apt install -y python3-tk")
        ok = False
    disp = os.environ.get("DISPLAY", "") or os.environ.get("WAYLAND_DISPLAY", "")
    if disp:
        print(f"[OK] GUI display: {disp}")
    else:
        print("[!] GUI display nahi mila — headless doctor check theek hai; GUI desktop session me kholo")
    if os.geteuid() == 0:
        print("[OK] ROOT mode me chal raha hai")
    else:
        print("[!] ROOT nahi (normal) — launch par password prompt aayega")
    for name in ("dpkg", "apt-get", "pkexec", "sudo"):
        found = shutil.which(name)
        if found:
            print(f"[OK] {name}")
        else:
            print(f"[X] {name} missing!")
            if name in ("dpkg", "apt-get"):
                ok = False
    import glob as _glob
    n_icons = len(_glob.glob("/usr/share/icons/*/64x64/apps/*.png")) + \
        len(_glob.glob("/usr/share/pixmaps/*.png"))
    n_desk = len(_glob.glob("/usr/share/applications/*.desktop"))
    print(f"[i] Icon sources: {n_desk} desktop files, "
          f"{n_icons} system app icons (tool icons yahin se aate hain)")
    if not is_root() and not (shutil.which("pkexec") or shutil.which("sudo")):
        print("[X] pkexec aur sudo dono missing — privilege elevation mumkin nahi")
        ok = False
    if ok:
        print("== RESULT: READY — 'kali-uninstaller' chalao ==")
    else:
        print("== RESULT: UPAR WALI PROBLEMS FIX KARO ==")
    return ok


# ---------------------------------------------------------- GUI imports ---
if __name__ == "__main__" and ("--doctor" in sys.argv or "--check" in sys.argv):
    raise SystemExit(0 if _run_doctor() else 1)

