        self.tree.tag_configure("odd", background=ROW_B, foreground=TXT)
        self.tree.tag_configure("crit", foreground=RED_DIM)
        self.tree.tag_configure("hover", background=ROW_HOV)
        self.tree.bind("<<TreeviewSelect>>", self._on_select)
        self.tree.bind("<Double-1>", lambda e: self.uninstall_selected())
        self.tree.bind("<Button-3>", self._popup_ctx)
        self.tree.bind("<Motion>", self._on_motion)
        self.tree.bind("<Leave>", self._on_leave)
        self.tree.bind("<Control-a>", lambda e: (self._select_all(), "break")[1])
        self.tree.bind("<Return>", lambda e: self.uninstall_selected())

        # bottom action bar (pack side=bottom first so others sit above it)
        bar = tk.Frame(self, bg=PANEL2)
        bar.pack(side="bottom", fill="x")
        self._bar = bar
